begin;
create function pg_temp.t12_user(p uuid) returns void language plpgsql set search_path=pg_catalog as $$
begin perform set_config('request.jwt.claim.sub',coalesce(p::text,''),true);perform set_config('request.jwt.claim.role','authenticated',true);end $$;
do $t$
declare
  admin uuid:='e1120000-0000-0000-0000-000000000101';cashier_a uuid:='e1120000-0000-0000-0000-000000000102';cashier_b uuid:='e1120000-0000-0000-0000-000000000103';waiter uuid:='e1120000-0000-0000-0000-000000000104';kitchen uuid:='e1120000-0000-0000-0000-000000000105';other uuid:='e1120000-0000-0000-0000-000000000106';
  la uuid:='e1120000-0000-0000-0000-000000000201';lb uuid:='e1120000-0000-0000-0000-000000000202';box uuid:='e1120000-0000-0000-0000-000000000301';boxb uuid:='e1120000-0000-0000-0000-000000000302';s uuid:='e1120000-0000-0000-0000-000000000401';sb uuid:='e1120000-0000-0000-0000-000000000402';mesa uuid:='e1120000-0000-0000-0000-000000000501';mesa_an uuid:='e1120000-0000-0000-0000-000000000502';mesab uuid:='e1120000-0000-0000-0000-000000000503';cat uuid:='e1120000-0000-0000-0000-000000000601';prod uuid:='e1120000-0000-0000-0000-000000000602';today date:=(now() at time zone 'America/Lima')::date;opened timestamptz:=(today+time '08:00') at time zone 'America/Lima';closed timestamptz:=(today+time '18:00') at time zone 'America/Lima';r record;checks int:=0;
begin
  if exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in('rpc_obtener_reportes_sesion_caja','rpc_obtener_resumen_diario_caja') and (not p.prosecdef or p.proowner<>(select oid from pg_roles where rolname='postgres') or p.proconfig<>array['search_path=pg_catalog'])) then raise exception 'TP58 metadata insegura';end if;
  if has_function_privilege('anon','public.rpc_obtener_resumen_diario_caja()','EXECUTE') or not has_function_privilege('authenticated','public.rpc_obtener_resumen_diario_caja()','EXECUTE') then raise exception 'TP58 grants inválidos';end if;checks:=checks+1;
  insert into auth.users(id,aud,role,email,encrypted_password) values(admin,'authenticated','authenticated','t12-a@example.invalid','x'),(cashier_a,'authenticated','authenticated','t12-ca@example.invalid','x'),(cashier_b,'authenticated','authenticated','t12-cb@example.invalid','x'),(waiter,'authenticated','authenticated','t12-w@example.invalid','x'),(kitchen,'authenticated','authenticated','t12-k@example.invalid','x'),(other,'authenticated','authenticated','t12-o@example.invalid','x');
  insert into public.local(id,codigo,nombre) values(la,'T12-A','Local A'),(lb,'T12-B','Local B');
  insert into public.perfil_usuario(id,local_id,rol_id,nombre) select admin,la,id,'Admin' from public.rol where codigo='ADMINISTRADOR' union all select cashier_a,la,id,'Caja A' from public.rol where codigo='CAJA' union all select cashier_b,la,id,'Caja B' from public.rol where codigo='CAJA' union all select waiter,la,id,'Mozo' from public.rol where codigo='MOZO' union all select kitchen,la,id,'Cocina' from public.rol where codigo='COCINA' union all select other,lb,id,'Caja otro' from public.rol where codigo='CAJA';
  insert into public.caja(id,local_id,codigo,nombre) values(box,la,'T12','Caja reporte'),(boxb,lb,'T12B','Caja B');
  insert into public.sesion_caja(id,caja_id,local_id,abierta_por,abierta_en,monto_inicial,idempotency_key,estado,cerrada_por,cerrada_en,efectivo_esperado,efectivo_contado,diferencia,motivo_diferencia) values(s,box,la,cashier_a,opened,100,'e1120000-0000-0000-0000-000000000701','CERRADA',cashier_b,closed,160,158,-2,'Faltante'),(sb,boxb,lb,other,opened,10,'e1120000-0000-0000-0000-000000000702','ABIERTA',null,null,null,null,null,null);
  insert into public.movimiento_caja(sesion_caja_id,caja_id,local_id,tipo,importe,motivo,actor_id,idempotency_key,creado_en) values(s,box,la,'ENTRADA',20,'Ingreso',cashier_b,'e1120000-0000-0000-0000-000000000703',opened+interval '1 hour'),(s,box,la,'SALIDA',5,'Egreso',cashier_a,'e1120000-0000-0000-0000-000000000704',opened+interval '2 hours');
  insert into public.resumen_cierre_sesion_caja values(s,box,la,cashier_b,closed,'NORMAL',40,5,50,2,0,0,0,0,20,5,160,158,-2,'Faltante');
  insert into public.mesa(id,local_id,codigo,nombre,estado) values(mesa,la,'M1','Mesa 1','LIBRE'),(mesa_an,la,'M2','Mesa 2','LIBRE'),(mesab,lb,'MB','Mesa B','LIBRE');insert into public.categoria(id,local_id,codigo,nombre) values(cat,la,'T12','Cat');insert into public.producto(id,local_id,categoria_id,codigo,nombre,precio) values(prod,la,cat,'T12','Producto',100);
  insert into public.pedido(id,local_id,mesa_id,creado_por,estado) overriding system value values(-11201,la,mesa,waiter,'PAGADO'),(-11202,la,mesa_an,waiter,'ANULADO'),(-11203,lb,mesab,other,'PAGADO');insert into public.detalle_pedido(id,pedido_id,producto_id,cantidad,precio_unitario,estado,enviado_en) overriding system value values(-11201,-11201,prod,1,100,'LISTO',opened),(-11202,-11202,prod,1,30,'LISTO',opened);
  insert into public.descuento_pedido(id,pedido_id,local_id,tipo,valor_solicitado,motivo,estado,solicitado_por,solicitud_idempotency_key,decidido_por,decidido_en,decision_idempotency_key,subtotal_base,importe_aplicado,total_neto) values('e1120000-0000-0000-0000-000000000801',-11201,la,'IMPORTE',10,'Promo','AUTORIZADO',cashier_a,'e1120000-0000-0000-0000-000000000802',admin,opened+interval '2 hours','e1120000-0000-0000-0000-000000000803',100,10,90);
  insert into public.pago(pedido_id,importe,medio,usuario_id,pagado_en,sesion_caja_id,propina,idempotency_key) values(-11201,40,'EFECTIVO',cashier_a,opened+interval '3 hours',s,5,'e1120000-0000-0000-0000-000000000901'),(-11201,50,'YAPE',cashier_b,opened+interval '4 hours',s,2,'e1120000-0000-0000-0000-000000000902');
  insert into public.anulacion_pedido(pedido_id,local_id,mesa_id,actor_id,motivo,estado_anterior,estado_nuevo,mesa_estado_anterior,mesa_estado_nuevo,anulado_en,idempotency_key) values(-11202,la,mesa_an,admin,'Sin stock','ENTREGADO','ANULADO','PENDIENTE_PAGO','LIBRE',opened+interval '5 hours','e1120000-0000-0000-0000-000000000903');
  perform pg_temp.t12_user(cashier_b);select * into r from public.rpc_obtener_reportes_sesion_caja(s);
  if r.abierta_por<>cashier_a or r.cerrada_por<>cashier_b or r.venta_efectivo<>40 or r.venta_yape<>50 or r.propina_efectivo<>5 or r.propina_yape<>2 or r.entradas<>20 or r.salidas<>5 or r.efectivo_esperado<>160 or r.efectivo_contado<>158 or r.diferencia<>-2 or r.descuentos<>10 or r.cantidad_anulaciones<>1 or r.cantidad_pagos<>2 or r.pagos_parciales<>2 or r.cantidad_pedidos_completados<>1 then raise exception 'TP56 reporte sesión inconciliable: %',r;end if;checks:=checks+1;
  select * into r from public.rpc_obtener_resumen_diario_caja();if r.fecha_operativa<>today or r.total_vendido<>90 or r.venta_efectivo<>40 or r.venta_yape<>50 or r.total_propinas<>7 or r.descuentos<>10 or r.cantidad_anulaciones<>1 or r.cantidad_pagos<>2 or r.pagos_parciales<>2 or r.cantidad_pedidos_completados<>1 then raise exception 'TP57 resumen diario incorrecto: %',r;end if;checks:=checks+1;
  perform pg_temp.t12_user(other);select * into r from public.rpc_obtener_resumen_diario_caja();if r.total_vendido<>0 or exists(select 1 from public.rpc_obtener_reportes_sesion_caja(s)) then raise exception 'TP58 fuga entre locales';end if;
  perform pg_temp.t12_user(waiter);begin perform public.rpc_obtener_resumen_diario_caja();raise exception 'MOZO autorizado';exception when insufficient_privilege then null;end;perform pg_temp.t12_user(kitchen);begin perform public.rpc_obtener_reportes_sesion_caja(null);raise exception 'COCINA autorizada';exception when insufficient_privilege then null;end;perform pg_temp.t12_user(null);begin perform public.rpc_obtener_resumen_diario_caja();raise exception 'anon autorizado';exception when insufficient_privilege then null;end;checks:=checks+1;
  raise notice 'E1-T12 grupos aprobados: %',checks;
end $t$;
select 'E1-T12 SQL: TP56-TP58 aprobados';
rollback;
